local lib = import("vtlib", {rootdir = os.scriptdir(), anonymous = true})

local PROLOGUE = [==[
#import <Foundation/Foundation.h>
#import <VideoToolbox/VideoToolbox.h>
#import "videotoolbox-cases.h"

// GENERATED by gen-constant-cases.py from ladder.tsv - do not hand-edit. The declarations below and the
// reads further down are what the ladder PLACES and the port DEFINES; a hand-copied list is a list that
// goes stale, and twelve kVTProfileLevel constants went exactly that way until this existed.
//
// The value of each is read out of WHICHER build is linked in: the host's own VideoToolbox, or the
// port's file with the names renamed. compare.py requires them to agree, one check per constant - and a
// value the host did not print is never written into the port.
//
// The two locals below are not tidiness. -[NSString UTF8String] is NS_RETURNS_INNER_POINTER, and
// casting the symbol inline inside the brackets makes the compiler read the whole thing as a
// message to a non-Objective-C pointer, which is twenty errors. A local of the right type first
// and the message on it is what compiles.
]==]

local HERE = os.scriptdir()
local WORKTREE = path.join(HERE, "..", "..", "..", "..")
local PACKAGE = path.join(WORKTREE, "packages", "frameworks", "apple-backports", "VideoToolbox")
local TABLE = path.join(HERE, "ladder.tsv")
local CASES = path.join(HERE, "cases.m")

local function wanted()
    local placed, native = {}, {}
    for _, row in ipairs(lib.ladder_rows(lib.read_text(TABLE))) do
        local release = lib.strip(row.release)
        if release == "" or release == "-" then
            native[row.name] = true
        else
            placed[row.name] = true
        end
    end
    local defined = {}
    for _, file in ipairs(lib.files_matching(PACKAGE, "VideoToolboxConstants*.m")) do
        for _, line in ipairs(lib.split_text(lib.read_text(file), "\n")) do
            local name = line:match("^const CFStringRef ([%w_]+) = CFSTR")
            if name then
                defined[name] = true
            end
        end
    end
    local missing, names = {}, {}
    for name in pairs(defined) do
        names[#names + 1] = name
        if not placed[name] and not native[name] then
            missing[#missing + 1] = name
        end
    end
    lib.sort_bytes(missing)
    if #missing > 0 then
        raise("AssertionError: these constants are defined but ladder.tsv does not measure them, so nothing says which "
            .. "object holds them: " .. lib.py_list(missing))
    end
    return lib.sort_bytes(names)
end

local function render(names)
    local out = { PROLOGUE }
    for _, name in ipairs(names) do
        out[#out + 1] = "extern const CFStringRef " .. name .. ";"
    end
    out[#out + 1] = ""
    out[#out + 1] = "void videotoolbox_run(CertificateRecorder record)"
    out[#out + 1] = "{"
    for _, name in ipairs(names) do
        out[#out + 1] = "    {"
        out[#out + 1] = "        NSString *value = (__bridge NSString *)(" .. name .. ");"
        out[#out + 1] = "        const char *utf8 = value.UTF8String;"
        out[#out + 1] = '        record(@"' .. name .. '", utf8 ? @(utf8) : @"(unreadable)");'
        out[#out + 1] = "    }"
    end
    out[#out + 1] = "}"
    return table.concat(out, "\n") .. "\n"
end

function main(...)
    local check = false
    for _, arg in ipairs({ ... }) do
        if arg == "--check" then
            check = true
        end
    end
    local names = wanted()
    local text = render(names)
    if check then
        local onDisk = lib.read_text(CASES)
        if onDisk == text then
            print(string.format("cases.m is what the ladder says: %d constants", #names))
            return
        end
        print(string.format("FAIL cases.m is not what the ladder says: %d constants on disk, %d generated",
            lib.count_plain(onDisk, "extern const CFStringRef"), #names))
        os.exit(1)
    end
    lib.write_text(CASES, text)
    print(string.format("cases.m written: %d constants", #names))
end
